template <typename T>
class Stack {
private:
    vector<T> elements;

public:
    void push(T const& elem) {
        elements.push_back(elem);
    }

    void pop() {
        if (elements.empty()) {
            throw out_of_range("Stack<>::pop(): empty stack");
        }
        elements.pop_back();
    }

    T top() const {
        if (elements.empty()) {
            throw out_of_range("Stack<>::top(): empty stack");
        }
        return elements.back();
    }

    bool empty() const {
        return elements.empty();
    }
};

int main() {
    Stack<int> intStack;
    intStack.push(7);
    cout << "Top element: " << intStack.top() << endl;
    intStack.pop();
    return 0;
}

